steps.script:
var sc = tree.current_scene.shooting_controller
var out: Array = []
var root = sc.weapon_tree.get_root()
var c = root.get_first_child() if root != null else null
while c != null:
	out.append(str(c.get_text(1)))
	c = c.get_next()
return "|".join(out)

var o = tree.root.get_node("/root/TutorialOverlay")
var t = str(o.current_body_text())
return t.find("Confirm") != -1 and t.find("lock 'em in") != -1

var t = tree.root.get_node_or_null("/root/TutorialOverlay/InstructorCard/Margin/VBox/BodyText")
if t == null:
	return "no card"
var s: String = str(t.text)
for needle in ["▲", "▼", "right-hand side", "savin' throws"]:
	if not s.contains(needle):
		return "card never mentions '%s'" % needle
return "ok"

var d = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/ResolutionDock")
if d == null or str(d.state) != "queued":
	return "dock not queued"
var n: int = d.assignments.size()
if n < 2:
	return "only %d weapon(s) queued" % n
for i in range(n):
	var row = d.queue_box.get_node_or_null("QueueRow%d" % i)
	if row == null or row.get_node_or_null("Up%d" % i) == null or row.get_node_or_null("Down%d" % i) == null:
		return "row %d is missing its ▲▼ buttons" % i
var ids: Array = []
for a in d.assignments:
	ids.append(str(a.get("weapon_id", "?")))
tree.root.set_meta("t4_order_before", ids)
return "ok"

var d = tree.root.get_node("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/ResolutionDock")
var before: Array = tree.root.get_meta("t4_order_before", [])
var after: Array = []
for a in d.assignments:
	after.append(str(a.get("weapon_id", "?")))
if before.size() != after.size():
	return "queue length changed"
if after[0] != before[1] or after[1] != before[0]:
	return "order unchanged: %s -> %s" % [str(before), str(after)]
for i in range(2, after.size()):
	if after[i] != before[i]:
		return "row %d moved too" % i
return "ok"

var b = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay/Center/Panel/Row/DecisionCol/ResultPanel/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay/Center/Panel/Row/DecisionCol/ResultPanel/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay/Center/Panel/Row/DecisionCol/ResultPanel/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/ResolutionDock/DockPrimaryButton")
if b != null and b.is_visible_in_tree() and str(b.text).begins_with("Complete"):
	b.pressed.emit()
	return true
var d = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay/Center/Panel/Row/DecisionCol/ResultPanel/DoneButton")
if d != null and d.is_visible_in_tree():
	d.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/ResolutionDock/DockPrimaryButton")
if b != null and b.is_visible_in_tree() and str(b.text).begins_with("Complete"):
	b.pressed.emit()
return true

var glp = tree.current_scene.game_log_panel
var sc = tree.current_scene.shooting_controller
return sc.dice_log_display == glp.get_dice_log_display()

var b = tree.root.get_node_or_null("/root/ShootingPhaseSummaryDialog/Content/Actions/ConfirmEndShooting")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return true
return false
